46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
68	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
69	     */
70	    /**
71	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
72	     * they can be routed and asserted independently of the application's diagnostic logging.
73	     */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /**
80	     * Common address abbreviations expanded to their full form during address normalization.
81	     * Matching is performed per whitespace-separated token on the upper-cased value.
82	     */
83	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
84	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.petMapper = petMapper;
101	        this.visitMapper = visitMapper;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        Owner owner = this.clinicService.findOwnerById(ownerId);
123	        if (owner == null) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        HttpHeaders headers = new HttpHeaders();
133	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
134	        LocalDate effectiveDate = owner.getRegistrationDate() != null
135	            ? owner.getRegistrationDate() : LocalDate.now();
136	        LocalDate registrationDate = toBusinessDay(effectiveDate);
137	        owner.setRegistrationDate(registrationDate);
138	        long createdToday = this.clinicService.findAllOwners().stream()
139	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
140	            .count();
141	        if (createdToday >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        owner.setBulkSignupWarning(createdToday > 80);
145	        String address = normalizeAddress(owner.getAddress());
146	        if (address == null || address.isEmpty()) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        owner.setAddress(address);
150	        String telephone = toE164(owner.getTelephone());
151	        if (telephone == null) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setTelephone(telephone);
155	        if (owner.getEmail() != null) {
156	            String email = normalizeEmail(owner.getEmail());
157	            if (!EMAIL_PATTERN.matcher(email).matches()) {
158	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
159	            }
160	            owner.setEmail(email);
161	        }
162	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
163	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
164	        if (telephoneInUse) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        String cityKey = householdKey(owner.getCity());
168	        long cityCount = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> existing.getCity() != null
170	                && cityKey.equals(householdKey(existing.getCity())))
171	            .count();
172	        if (cityCount >= 50) {
173	            return new ResponseEntity<>(HttpStatus.CONFLICT);
174	        }
175	        String lastNameKey = householdKey(owner.getLastName());
176	        String addressKey = householdKey(owner.getAddress());
177	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
178	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
179	                && addressKey.equals(householdKey(existing.getAddress())))
180	            .toList();
181	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
182	            String householdId = householdMembers.stream()
183	                .map(Owner::getHouseholdId)
184	                .filter(Objects::nonNull)
185	                .findFirst()
186	                .orElseGet(() -> householdId(owner));
187	            owner.setHouseholdId(householdId);
188	            for (Owner member : householdMembers) {
189	                if (member.getHouseholdId() == null) {
190	                    member.setHouseholdId(householdId);
191	                    this.clinicService.saveOwner(member);
192	                }
193	            }
194	            owner.setHouseholdSize(householdMembers.size() + 1);
195	        } else if (!householdMembers.isEmpty()) {
196	            return new ResponseEntity<>(HttpStatus.CONFLICT);
197	        } else {
198	            owner.setHouseholdSize(1);
199	        }
200	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
201	        String firstNameKey = householdKey(owner.getFirstName());
202	        String namesakeLastNameKey = householdKey(owner.getLastName());
203	        long namesakeCount = this.clinicService.findAllOwners().stream()
204	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
205	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
206	            .count();
207	        owner.setNamesakeCount((int) namesakeCount);
208	        this.clinicService.saveOwner(owner);
209	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
210	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
211	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
215	    }
216	
217	    /**
218	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
219	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
220	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
221	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
222	     *
223	     * @param telephone the raw telephone value (may be {@code null})
224	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
225	     *         a valid E.164 number
226	     */
227	    private String toE164(String telephone) {
228	        if (telephone == null) {
229	            return null;
230	        }
231	        String trimmed = telephone.trim();
232	        boolean hasCountryCode = trimmed.startsWith("+");
233	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
234	        if (hasCountryCode) {
235	            cleaned = cleaned.substring(1);
236	        }
237	        if (!cleaned.matches("[0-9]+")) {
238	            return null;
239	        }
240	        String digits;
241	        if (hasCountryCode) {
242	            digits = cleaned;
243	        } else {
244	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
245	            digits = "61" + national;
246	        }
247	        if (digits.length() < 8 || digits.length() > 15) {
248	            return null;
249	        }
250	        return "+" + digits;
251	    }
252	
253	    /**
254	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
255	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
256	     *
257	     * @param email the raw email value (must not be {@code null})
258	     * @return the trimmed, lower-cased email
259	     */
260	    private String normalizeEmail(String email) {
261	        return email.trim().toLowerCase(Locale.ROOT);
262	    }
263	
264	    /**
265	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
266	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
267	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
268	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
269	     * normalized form, and every household comparison uses it.
270	     *
271	     * @param address the raw address value (may be {@code null})
272	     * @return the normalized address, or {@code null} if the input was {@code null}
273	     */
274	    private String normalizeAddress(String address) {
275	        if (address == null) {
276	            return null;
277	        }
278	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
279	        if (collapsed.isEmpty()) {
280	            return collapsed;
281	        }
282	        String[] tokens = collapsed.split(" ");
283	        StringBuilder sb = new StringBuilder(collapsed.length());
284	        for (int i = 0; i < tokens.length; i++) {
285	            if (i > 0) {
286	                sb.append(' ');
287	            }
288	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
289	        }
290	        return sb.toString();
291	    }
292	
293	    /**
294	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
295	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
296	     * so that owners are compared case-insensitively with collapsed whitespace.
297	     *
298	     * @param value the raw value (must not be {@code null})
299	     * @return the normalized comparison key
300	     */
301	    private String householdKey(String value) {
302	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
303	    }
304	
305	    /**
306	     * Derives a stable, shared household identifier for the owner's household. The value is a
307	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
308	     * every owner in the same household derives the identical identifier of the form
309	     * {@code 'HH-<12 upper-case hex>'}.
310	     *
311	     * @param owner the owner whose household identifier is derived
312	     * @return the stable household identifier
313	     */
314	    private String householdId(Owner owner) {
315	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
316	        try {
317	            byte[] digest = MessageDigest.getInstance("SHA-256")
318	                .digest(key.getBytes(StandardCharsets.UTF_8));
319	            StringBuilder sb = new StringBuilder(digest.length * 2);
320	            for (byte b : digest) {
321	                sb.append(String.format("%02x", b));
322	            }
323	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
324	        }
325	        catch (java.security.NoSuchAlgorithmException e) {
326	            throw new IllegalStateException("SHA-256 not available", e);
327	        }
328	    }
329	
330	    /**
331	     * Builds the customer code for a newly registered owner in the form
332	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
333	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
334	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
335	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
336	     *
337	     * @param city     the owner's city
338	     * @param lastName the owner's last name
339	     * @return the assigned customer code
340	     */
341	    private String nextCustomerCode(String city, String lastName) {
342	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
343	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
344	        String cityKey = householdKey(city);
345	        int sequence = (int) this.clinicService.findAllOwners().stream()
346	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
347	            .count() + 1;
348	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
349	    }
350	
351	    /**
352	     * Rolls a registration date forward onto a business day. When the given date falls on a
353	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
354	     *
355	     * @param date the effective registration date (must not be {@code null})
356	     * @return the same date if it is a weekday, otherwise the next Monday
357	     */
358	    private LocalDate toBusinessDay(LocalDate date) {
359	        DayOfWeek dayOfWeek = date.getDayOfWeek();
360	        if (dayOfWeek == DayOfWeek.SATURDAY) {
361	            return date.plusDays(2);
362	        }
363	        if (dayOfWeek == DayOfWeek.SUNDAY) {
364	            return date.plusDays(1);
365	        }
366	        return date;
367	    }
368	
369	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
370	    @Override
371	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
372	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
373	        if (currentOwner == null) {
374	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
375	        }
376	        String email = ownerFieldsDto.getEmail();
377	        if (email != null) {
378	            email = normalizeEmail(email);
379	            if (!EMAIL_PATTERN.matcher(email).matches()) {
380	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
381	            }
382	        }
383	        String telephone = toE164(ownerFieldsDto.getTelephone());
384	        if (telephone == null) {
385	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
386	        }
387	        currentOwner.setAddress(ownerFieldsDto.getAddress());
388	        currentOwner.setCity(ownerFieldsDto.getCity());
389	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
390	        currentOwner.setLastName(ownerFieldsDto.getLastName());
391	        currentOwner.setTelephone(telephone);
392	        currentOwner.setEmail(email);
393	        this.clinicService.saveOwner(currentOwner);
394	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
395	    }
396	
